files.style.css:
:root{--bg:#0b0f19;--card:#141d2b;--card2:#1a2434;--line:#26324b;--txt:#eef2fb;--dim:#94a3c4;
        --green:#34d399;--red:#fb7185;--amber:#fbbf24;--violet:#7c6cf8;--cyan:#22d3ee}
  *{box-sizing:border-box;-webkit-tap-highlight-color:transparent}
  html,body{height:100%}
  body{margin:0;background:var(--bg);color:var(--txt);font-family:system-ui,-apple-system,"Segoe UI",Roboto,"Noto Sans Devanagari",sans-serif;
       display:flex;flex-direction:column;font-size:15px}
  header{padding:11px 14px;background:#0e1520;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:8px}
  .logo{font-weight:800;font-size:16px}
  .logo span{color:var(--green)}
  .pill{font-size:11px;color:var(--dim);border:1px solid var(--line);border-radius:20px;padding:2px 8px}
  .spacer{flex:1}
  main{flex:1;overflow:auto;padding:14px;padding-bottom:80px}
  .view{display:none}
  .view.on{display:block}
  h2{font-size:16px;margin:0 0 10px}
  .card{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:13px;margin-bottom:10px}
  .row{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:9px 0;border-bottom:1px solid rgba(255,255,255,.05)}
  .row:last-child{border-bottom:0}
  .nm{font-weight:600;font-size:14px}
  .sub{color:var(--dim);font-size:12px}
  .up{color:var(--green)} .down{color:var(--red)}
  button{background:var(--card2);border:1px solid var(--line);color:var(--txt);border-radius:11px;padding:12px 14px;
         font-size:14px;font-weight:700;font-family:inherit;cursor:pointer}
  button.pri{background:linear-gradient(135deg,var(--violet),#3b82f6);border:0}
  button.ok{background:var(--green);color:#04170c;border:0}
  input,textarea,select{width:100%;background:#0b1119;border:1px solid var(--line);color:var(--txt);
        border-radius:11px;padding:12px;font-size:14.5px;font-family:inherit;margin-bottom:8px}
  .grid2{display:grid;grid-template-columns:1fr 1fr;gap:8px}
  .tile{background:var(--card2);border:1px solid var(--line);border-radius:13px;padding:14px;text-align:center}
  .tile b{display:block;font-size:15px;margin-bottom:3px}
  .tile span{font-size:11.5px;color:var(--dim)}
  .ok-dot{width:9px;height:9px;border-radius:50%;display:inline-block;margin-right:6px;background:var(--dim)}
  .ok-dot.g{background:var(--green)} .ok-dot.r{background:var(--red)} .ok-dot.a{background:var(--amber)}
  nav{position:fixed;bottom:0;left:0;right:0;display:flex;background:#0e1520;border-top:1px solid var(--line);
      padding-bottom:env(safe-area-inset-bottom);z-index:9}
  nav button{flex:1;background:transparent;border:0;color:var(--dim);font-size:11px;font-weight:700;
             display:flex;flex-direction:column;align-items:center;gap:3px;padding:9px 2px 11px;border-radius:0}
  nav button .ic{font-size:18px}
  nav button.on{color:var(--green)}
  .toast{position:fixed;left:50%;transform:translateX(-50%);bottom:78px;background:#1f2a3d;border:1px solid var(--line);
         color:var(--txt);padding:10px 16px;border-radius:20px;font-size:13px;opacity:0;transition:.25s;z-index:20}
  .toast.on{opacity:1}

