const $ = (id) => document.getElementById(id);
const LS = {
  get(k, d){ try{ const v = localStorage.getItem("seetal." + k); return v === null ? d : JSON.parse(v); }catch(e){ return d; } },
  set(k, v){ try{ localStorage.setItem("seetal." + k, JSON.stringify(v)); }catch(e){} }
};
function toast(m){ const t = $("toast"); t.textContent = m; t.classList.add("on"); setTimeout(() => t.classList.remove("on"), 1800); }

/* ---------- views ---------- */
document.querySelectorAll("nav button").forEach(b => b.onclick = () => show(b.dataset.v));
document.querySelectorAll("[data-go]").forEach(t => t.onclick = () => show(t.dataset.go));
function show(v){
  document.querySelectorAll(".view").forEach(x => x.classList.toggle("on", x.id === "v-" + v));
  document.querySelectorAll("nav button").forEach(x => x.classList.toggle("on", x.dataset.v === v));
  if (v === "trader") loadData();
  if (v === "vault") paintVault();
  if (v === "notes") { $("notes").value = LS.get("notes", ""); paintNotes(); }
  if (v === "sync") $("syncCode").value = LS.get("synccode", "");
}

/* ---------- data ---------- */
const SOURCES = [
  "https://raw.githubusercontent.com/bhupendarsingh785/seetal-trader/main/data/live.json",
  "https://seetal-api.bhupendarsingh785.workers.dev/live",
  "data/live.json"
];
let DATA = null;

async function loadData(force){
  if (DATA && !force) return DATA;
  const cached = LS.get("livecache", null);
  if (cached && !force){ DATA = cached; paintTrader(); }

  for (const url of SOURCES){
    try{
      const r = await fetch(url + (url.includes("?") ? "&" : "?") + "t=" + Date.now(), { cache: "no-store" });
      if (!r.ok) continue;
      let j = await r.json();
      const d = j && j.data ? j.data : j;
      if (d && d.rows && d.rows.length){
        DATA = d;
        LS.set("livecache", d);
        paintTrader();
        return d;
      }
    }catch(e){}
  }
  if (!DATA) $("traderList").innerHTML = '<div class="sub">Data nahi mila — net check karo.</div>';
  return DATA;
}

function paintTrader(){
  if (!DATA) return;
  const rows = DATA.rows || [];
  const gen = DATA.generated_at ? new Date(DATA.generated_at) : null;
  const age = gen ? Math.round((Date.now() - gen.getTime()) / 60000) : null;

  $("dataAge").textContent = age === null ? "—" : (age + " min purana");
  $("dataSrc").textContent = DATA.source || "live";
  $("dataCount").textContent = rows.length;
  $("hstat").textContent = age === null ? "?" : (age + " min");

  $("traderList").innerHTML = rows.map(r => {
    const pct = Number(r.change_pct || 0);
    const cls = pct >= 0 ? "up" : "down";
    const state = r.state || "WAIT";
    const st = state === "ENTRY" ? "🟢 ENTRY" : (state === "WAIT" ? "⏳ WAIT" : state);
    return '<div class="row">'
      + '<div><div class="nm">' + (r.name || r.symbol) + '</div>'
      + '<div class="sub">' + st + (r.distance_pct != null ? " · " + Number(r.distance_pct).toFixed(2) + "% door" : "") + '</div></div>'
      + '<div style="text-align:right"><div class="nm">' + (r.last != null ? Number(r.last).toFixed(2) : "—") + '</div>'
      + '<div class="sub ' + cls + '">' + (pct >= 0 ? "+" : "") + pct.toFixed(2) + '%</div></div>'
      + '</div>';
  }).join("") || '<div class="sub">Koi row nahi.</div>';
}

/* ---------- doctor ---------- */
const CHECKS = [
  { n: "Trader data", u: "https://bhupendarsingh785.github.io/seetal-trader/data/live.json" },
  { n: "Cloudflare API", u: "https://seetal-api.bhupendarsingh785.workers.dev/status" },
  { n: "Netlify", u: "https://seetal-trader.netlify.app/" },
  { n: "Vercel", u: "https://bhupendarsingh785.vercel.app/" },
  { n: "Suno", u: "https://bhupendarsingh785.github.io/suno-assistant/" },
  { n: "Studio Pro", u: "https://bhupendarsingh785.github.io/seetal-trader/studio-pro.html" },
  { n: "Platform", u: "https://bhupendarsingh785.github.io/swag-page/platform/" }
];

$("docRun").onclick = async () => {
  const box = $("docOut");
  box.innerHTML = '<div class="sub">Jaanch chal rahi hai…</div>';
  let ok = 0;
  const lines = [];
  for (const c of CHECKS){
    const t0 = performance.now();
    let good = false, ms = 0;
    try{
      const r = await fetch(c.u + (c.u.includes("?") ? "&" : "?") + "t=" + Date.now(), { cache: "no-store" });
      ms = Math.round(performance.now() - t0);
      good = r.ok;
    }catch(e){ ms = Math.round(performance.now() - t0); }
    if (good) ok++;
    lines.push('<div class="row"><span class="nm"><span class="ok-dot ' + (good ? "g" : "r") + '"></span>' + c.n + '</span><span class="sub">' + (good ? ms + " ms" : "band") + '</span></div>');
  }
  // storage + cache
  let used = 0;
  try{ for (const k in localStorage) if (Object.prototype.hasOwnProperty.call(localStorage, k)) used += (localStorage[k] || "").length; }catch(e){}
  lines.push('<div class="row"><span class="nm"><span class="ok-dot ' + (used < 3000000 ? "g" : "a") + '"></span>Storage</span><span class="sub">' + Math.round(used / 1024) + ' KB</span></div>');

  const pct = Math.round(ok / CHECKS.length * 100);
  box.innerHTML = '<div style="font-size:15px;font-weight:800;margin-bottom:8px" class="' + (pct >= 90 ? "up" : pct >= 60 ? "" : "down") + '">Score: ' + pct + ' / 100 (' + ok + '/' + CHECKS.length + ')</div>' + lines.join("");
};

/* ---------- notes ---------- */
function paintNotes(){
  const v = $("notes").value || "";
  $("notesStat").textContent = v.length + " akshar · " + (v.trim() ? v.trim().split(/\s+/).length + " shabd" : "khali");
}
$("notes").addEventListener("input", () => { LS.set("notes", $("notes").value); paintNotes(); });

/* ---------- vault ---------- */
function paintVault(){
  const list = LS.get("vault", []);
  $("vList").innerHTML = list.length ? list.map((x, i) =>
    '<div class="row"><div><div class="nm">' + esc(x.title) + '</div><div class="sub">' + esc(x.user) + '</div></div>'
    + '<div style="display:flex;gap:6px"><button data-copy="' + i + '" style="padding:8px 10px;font-size:12px">copy</button>'
    + '<button data-del="' + i + '" style="padding:8px 10px;font-size:12px;color:#fb7185">✕</button></div></div>'
  ).join("") : '<div class="sub">Abhi kuch nahi.</div>';

  $("vList").querySelectorAll("[data-copy]").forEach(b => b.onclick = () => {
    const x = LS.get("vault", [])[Number(b.dataset.copy)];
    if (!x) return;
    navigator.clipboard.writeText(x.pass || "").then(() => toast("Password copy ho gaya")).catch(() => toast("Copy nahi hua"));
  });
  $("vList").querySelectorAll("[data-del]").forEach(b => b.onclick = () => {
    const list = LS.get("vault", []);
    list.splice(Number(b.dataset.del), 1);
    LS.set("vault", list); paintVault();
  });
}

$("vAdd").onclick = () => {
  const t = $("vTitle").value.trim(), u = $("vUser").value.trim(), p = $("vPass").value;
  if (!t) return toast("Naam likho");
  const list = LS.get("vault", []);
  list.unshift({ title: t, user: u, pass: p, t: Date.now() });
  LS.set("vault", list.slice(0, 100));
  $("vTitle").value = ""; $("vUser").value = ""; $("vPass").value = "";
  paintVault(); toast("Save ho gaya");
};

function esc(s){ return String(s == null ? "" : s).replace(/[&<>"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c])); }

/* ---------- sync (Supabase) ---------- */
const SUPA = "https://urvhrcyuqepzpbklonrz.supabase.co/rest/v1/seetal_sync";
const SKEY = "sb_publishable_R1qExbRPEz5d-8YEpDUc_Q_dSel34jw";
const SYNC_FIELDS = ["notes", "vault", "synccode", "livecache", "mirrors"];

function syncHeaders(){ return { apikey: SKEY, Authorization: "Bearer " + SKEY, "Content-Type": "application/json" }; }

async function syncPush(){
  const code = $("syncCode").value.trim();
  if (!code) return toast("Pehle code likho");
  LS.set("synccode", code);
  const data = {};
  SYNC_FIELDS.forEach(k => { const v = LS.get(k, null); if (v !== null) data[k] = v; });
  data.__at = new Date().toISOString();
  try{
    const r = await fetch(SUPA + "?on_conflict=code", {
      method: "POST",
      headers: Object.assign(syncHeaders(), { Prefer: "resolution=merge-duplicates,return=minimal" }),
      body: JSON.stringify({ code, data, updated_at: new Date().toISOString() })
    });
    $("syncOut").textContent = r.ok ? "✅ Bhej diya (" + Object.keys(data).length + " cheezein)" : ("❌ Fail " + r.status);
  }catch(e){ $("syncOut").textContent = "❌ Net issue: " + e.message; }
}

async function syncPull(){
  const code = $("syncCode").value.trim();
  if (!code) return toast("Pehle code likho");
  LS.set("synccode", code);
  try{
    const r = await fetch(SUPA + "?code=eq." + encodeURIComponent(code) + "&select=data,updated_at", { headers: syncHeaders() });
    const rows = await r.json();
    if (!rows || !rows.length){ $("syncOut").textContent = "Is code par kuch nahi mila."; return; }
    const d = rows[0].data || {};
    let n = 0;
    Object.keys(d).forEach(k => { if (SYNC_FIELDS.indexOf(k) !== -1){ LS.set(k, d[k]); n++; } });
    $("syncOut").textContent = "✅ " + n + " cheezein aa gayi — page refresh karo.";
    paintVault();
  }catch(e){ $("syncOut").textContent = "❌ Net issue: " + e.message; }
}

$("syncSave").onclick = () => { const c = $("syncCode").value.trim(); if (!c) return toast("Code likho"); LS.set("synccode", c); toast("Code save ho gaya"); };
$("syncUp").onclick = syncPush;
$("syncDown").onclick = syncPull;
$("syncGen").onclick = () => {
  const rnd = Math.random().toString(36).slice(2, 8) + Math.random().toString(36).slice(2, 8);
  $("syncCode").value = "seetal-" + rnd;
  LS.set("synccode", $("syncCode").value);
  toast("Naya code bana — save karo");
};

/* ---------- start ---------- */
$("refresh").onclick = () => { loadData(true).then(() => toast("Refresh ho gaya")); };
$("syncCode").value = LS.get("synccode", "");
loadData();
paintVault();

/* app ki tarah install + offline */
if ('serviceWorker' in navigator){
  navigator.serviceWorker.register('sw.js').catch(() => {});
}
